/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Tests
 *   - only confirmed capabilities allow Admin; selecting a view changes no account epoch
 *   - view switch retains private edits but fences old reads, account change clears everything
 *   - A to B to A never revives an earlier operation or editing buffer
 *   - a reload request survives view selection, suspension and authorization, and a reset clears it
 *   - a saved Admin view restores only after capabilities authorize the same account again
 *   - an explicit User view persists and new accounts still start in User view
 *   - account reconciliation restores the view without reviving private buffers or stale operations
 *   - each administrator restores only their own selection after an A to B to A transition
 *   - suspension and permission resets never replace a saved preference or accept stale capability responses
 *   - unavailable storage never prevents capability authorization or explicit view changes
 * @end-catalog */

import { advanceAccountEpoch, captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { adminViewPreferenceKey } from './adminViewPreference';

beforeEach(() => { window.localStorage.clear(); adminWorkspace.reset(); });
afterEach(() => { adminWorkspace.reset(); vi.restoreAllMocks(); });
test('only confirmed capabilities allow Admin; selecting a view changes no account epoch', () => {
  adminWorkspace.select('admin'); expect(adminWorkspace.getSnapshot().mode).toBe('user');
  const guard = captureAccountOperation('a');
  adminWorkspace.authorize(guard, true, false); adminWorkspace.select('admin');
  expect(adminWorkspace.capture()).toMatchObject(guard);
  adminWorkspace.select('user');
  expect(captureAccountOperation('a')).toEqual(guard);
});
test('view switch retains private edits but fences old reads, account change clears everything', () => {
  adminWorkspace.authorize(captureAccountOperation('a'), true, true); adminWorkspace.select('admin');
  const guard = adminWorkspace.capture(); adminWorkspace.retain('draft', { title: 'Manual' }, guard);
  adminWorkspace.select('user');
  expect(adminWorkspace.current(guard)).toBe(false);
  expect(adminWorkspace.current(guard, false)).toBe(true);
  expect(adminWorkspace.buffer('draft')).toEqual({ title: 'Manual' });
  advanceAccountEpoch();
  expect(adminWorkspace.buffer('draft')).toBeUndefined();
  expect(adminWorkspace.current(guard, false)).toBe(false);
  adminWorkspace.authorize(guard, true, true);
  expect(adminWorkspace.getSnapshot().authorized).toBe(false);
});
test('A to B to A never revives an earlier operation or editing buffer', () => {
  adminWorkspace.authorize(captureAccountOperation('a'), true, true); adminWorkspace.select('admin');
  const first = adminWorkspace.capture(); adminWorkspace.retain('draft', 'private', first);
  advanceAccountEpoch(); adminWorkspace.authorize(captureAccountOperation('b'), true, true);
  advanceAccountEpoch(); adminWorkspace.authorize(captureAccountOperation('a'), true, true);
  expect(adminWorkspace.current(first, false)).toBe(false);
  expect(adminWorkspace.buffer('draft')).toBeUndefined();
});
test('a reload request survives view selection, suspension and authorization, and a reset clears it', () => {
  const guard = captureAccountOperation('a'); adminWorkspace.authorize(guard, true, true); adminWorkspace.select('admin');
  adminWorkspace.requireReload(); expect(adminWorkspace.getSnapshot().reloadRequired).toBe(true);
  adminWorkspace.select('user'); adminWorkspace.suspend(); adminWorkspace.authorize(guard, true, true); adminWorkspace.select('admin');
  expect(adminWorkspace.getSnapshot().reloadRequired).toBe(true);
  adminWorkspace.reset(); expect(adminWorkspace.getSnapshot().reloadRequired).toBe(false);
});

test('a saved Admin view restores only after capabilities authorize the same account again', () => {
  const guard = captureAccountOperation('a');
  adminWorkspace.authorize(guard, true, true); adminWorkspace.select('admin');
  expect(window.localStorage.getItem(adminViewPreferenceKey('a'))).toBe('admin');
  adminWorkspace.reset();
  expect(adminWorkspace.getSnapshot()).toMatchObject({ mode: 'user', authorized: false });
  expect(() => adminWorkspace.capture()).toThrow();
  adminWorkspace.authorize(guard, true, true);
  expect(adminWorkspace.getSnapshot()).toMatchObject({ mode: 'admin', authorized: true });
});

test('an explicit User view persists and new accounts still start in User view', () => {
  adminWorkspace.authorize(captureAccountOperation('a'), true, true); adminWorkspace.select('admin');
  adminWorkspace.select('user'); adminWorkspace.reset();
  adminWorkspace.authorize(captureAccountOperation('a'), true, true);
  expect(adminWorkspace.getSnapshot().mode).toBe('user');
  advanceAccountEpoch(); adminWorkspace.authorize(captureAccountOperation('b'), true, true);
  expect(adminWorkspace.getSnapshot().mode).toBe('user');
  expect(window.localStorage.getItem(adminViewPreferenceKey('b'))).toBeNull();
});

test('account reconciliation restores the view without reviving private buffers or stale operations', () => {
  adminWorkspace.authorize(captureAccountOperation('a'), true, true); adminWorkspace.select('admin');
  const first = adminWorkspace.capture(); adminWorkspace.retain('draft', 'private', first);
  advanceAccountEpoch();
  expect(adminWorkspace.getSnapshot()).toMatchObject({ mode: 'user', authorized: false });
  adminWorkspace.authorize(first, true, true);
  expect(adminWorkspace.getSnapshot().authorized).toBe(false);
  adminWorkspace.authorize(captureAccountOperation('a'), true, true);
  expect(adminWorkspace.getSnapshot().mode).toBe('admin');
  expect(adminWorkspace.buffer('draft')).toBeUndefined();
  expect(adminWorkspace.current(first, false)).toBe(false);
});

test('each administrator restores only their own selection after an A to B to A transition', () => {
  adminWorkspace.authorize(captureAccountOperation('a'), true, true); adminWorkspace.select('admin');
  advanceAccountEpoch(); adminWorkspace.authorize(captureAccountOperation('b'), true, true);
  expect(adminWorkspace.getSnapshot().mode).toBe('user');
  adminWorkspace.select('user');
  advanceAccountEpoch(); adminWorkspace.authorize(captureAccountOperation('a'), true, true);
  expect(adminWorkspace.getSnapshot().mode).toBe('admin');
  expect(window.localStorage.getItem(adminViewPreferenceKey('b'))).toBe('user');
});

test('suspension and permission resets never replace a saved preference or accept stale capability responses', () => {
  const guard = captureAccountOperation('a');
  adminWorkspace.authorize(guard, true, true); adminWorkspace.select('admin');
  const authority = adminWorkspace.getSnapshot().authority;
  adminWorkspace.suspend(); adminWorkspace.select('user');
  expect(window.localStorage.getItem(adminViewPreferenceKey('a'))).toBe('admin');
  adminWorkspace.reset(); adminWorkspace.authorize(guard, true, true, authority);
  expect(adminWorkspace.getSnapshot().authorized).toBe(false);
  expect(window.localStorage.getItem(adminViewPreferenceKey('a'))).toBe('admin');
});

test.each(['', 'ADMIN', '"admin"', '{"mode":"admin"}', 'admin\n'])(
  'invalid stored selection %j falls back to User without changing the stored record', value => {
    window.localStorage.setItem(adminViewPreferenceKey('a'), value);
    adminWorkspace.authorize(captureAccountOperation('a'), true, true);
    expect(adminWorkspace.getSnapshot().mode).toBe('user');
    expect(window.localStorage.getItem(adminViewPreferenceKey('a'))).toBe(value);
  }
);

test('unavailable storage never prevents capability authorization or explicit view changes', () => {
  vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => { throw new Error('blocked'); });
  vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => { throw new Error('full'); });
  adminWorkspace.authorize(captureAccountOperation('a'), true, true);
  expect(adminWorkspace.getSnapshot().mode).toBe('user');
  expect(() => adminWorkspace.select('admin')).not.toThrow();
  expect(adminWorkspace.getSnapshot().mode).toBe('admin');
  adminWorkspace.suspend(); adminWorkspace.authorize(captureAccountOperation('a'), true, true);
  expect(adminWorkspace.getSnapshot().mode).toBe('admin');
});
